"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[77349],{16031:(e,t,i)=>{i.d(t,{Ay:()=>a,RM:()=>r});var o=i(74848),n=i(28453);const r=[];function s(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"the-management-finally-got-it-right-again",children:"The Management Finally Got It Right Again"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2007/11/21 15:36:59"}),"\n"]}),"\n",(0,o.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,o.jsx)(t.p,{children:"Today, the most important news concerns the ordering of A-share and H-share listings. Today's relatively official statement proves that the importance of A-shares has once again been strengthened. The fate of Hong Kong stocks being absorbed is irreversible\u2014it's only a matter of time. More importantly, what this ID has been loudly calling for everywhere over the past N months\u2014to dramatically increase the float ratio of large-cap A-shares\u2014has finally found a concrete solution. Going forward, the issue is that newly issued large-cap stocks must meet a minimum 10% float ratio. The speculative blue chips of the past will no longer appear."}),(0,o.jsx)(t.p,{children:"Today's news has both positive and negative implications. Positive effects: 1. The importance of A-shares will increase dramatically. 2. The current illegitimate speculative blue chips will paradoxically become rare commodities\u2014once index futures launch, the significance of controlling these stocks will increase even further. Negative effects: 1. How to resolve the historical problem of formerly low-float blue chips. 2. Future expansion pressure will further intensify\u2014since float ratios are increasing, excessively high prices will be affected."}),(0,o.jsx)(t.p,{children:"Currently, the broader market is technically in a mid-shade phase, and policy-wise it's the same. Therefore, the breakout direction of this mid-shade phase is very important. Of course, a downward breakout wouldn't be the end of the world\u2014it would just leave room for next year's market."}),(0,o.jsx)(t.p,{children:"The biggest variable going forward remains the futures issue."}),(0,o.jsx)(t.p,{children:"In terms of individual stocks, today was about PetroChina splitting, so the broader market saw amplified up-and-down gyrations\u2014this was also a good test of market control. For the broader market to truly hold, PetroChina must first stabilize in unison."}),(0,o.jsx)(t.p,{children:"The moon is nearly full, and everyone is getting restless. Whether there'll be another farce of \"heaven-and-man becoming one\"\u2014we'll find out very soon."}),(0,o.jsx)(t.p,{children:"As for other individual stocks, this ID doesn't feel like talking about overly small-cap stocks right now. Like that geometric progression stock\u2014this time during the adjustment, it got chopped in half in one go. That's the risk of small-cap stocks. Actually, this ID recently started a new arithmetic progression stock: slightly bigger market cap than the geometric one, priced at just over 7 yuan after rising, with an even smaller market value than the geometric one, but it's also ST\u2014so I've never mentioned it. Other stocks are all waiting for opportunities from the tossing around, but with the broader market direction undecided, this ID still has aspirations of turning reality into dreams."}),(0,o.jsx)(t.p,{children:"Having reached moderate prosperity, the next question is whether to aim for comprehensive moderate prosperity or the more ambitious goal of full prosperity\u2014this is indeed a very practical question. But one thing is certain: as I said yesterday, even if there's another breakdown, the probability of it being a trap increases."}),(0,o.jsx)(t.p,{children:"Another phone call\u2014they say the person has arrived. No choice, can't say more, have to go."}),(0,o.jsx)(t.p,{children:"Logging off now. See you."})]})]})}function a(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(s,{...e})}):s(e)}},28453:(e,t,i)=>{i.d(t,{R:()=>s,x:()=>a});var o=i(96540);const n={},r=o.createContext(n);function s(e){const t=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(r.Provider,{value:t},e.children)}},37852:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>c,contentTitle:()=>l,default:()=>u,frontMatter:()=>a,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"economics/rightagain","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/economics/rightagain.md","sourceDirName":"economics","slug":"/economics/rightagain","permalink":"/economics/rightagain","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"rightagain","title":"","hide_table_of_contents":true},"sidebar":"economicsSidebar","previous":{"title":"\u5feb\u70b9\u89e3\u76d8\uff0c\u5426\u5219\u8981\u723d\u7ea6\u3002 (2007/11/20 23:44:07)","permalink":"/economics/quickmarketanalysis"},"next":{"title":"\u53c8\u662f\u6708\u4eae\u60f9\u7684\u7978 (2007/11/22 15:32:48)","permalink":"/economics/moontroublemaker"}}');var n=i(74848),r=i(28453),s=i(16031);const a={id:"rightagain",title:"",hide_table_of_contents:!0},l=void 0,c={},h=[...s.RM];function d(e){return(0,n.jsx)(s.Ay,{})}function u(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d()}}}]);